INSERT OVERWRITE TABLE ${schema}.dwd_sr_data_warehouse_ssp_item_link_hf
partition(grass_region = ${grass_region}, local_date, local_hour, regional_date,regional_hour)
select
     item_id
    ,shop_id
    ,spu_id
    ,scene
    ,update_time

    ,date(date_timezone_convert(${regional_date},${regional_hour},'SG',${grass_region},"yyyy-MM-dd")) as local_date
    ,cast(date_timezone_convert(${regional_date},${regional_hour},'SG',${grass_region},"HH") as int) as local_hour
    ,cast(${regional_date} as date) as regional_date
    ,cast(${regional_hour} as int) as regional_hour
from(
    select
         item_id
        ,shop_id
        ,cast(get_json_object(spu_info,'$.spu_id') as bigint) as spu_id
        ,cast(get_json_object(spu_info,'$.scene') as int) as scene
        ,update_time
    from paimon.rcmd_feature.ods_sr_data_warehouse_ssp_item_link
    lateral view explode(spu_infos) as spu_info
    where grass_region in (${grass_region}) and spu_infos is not null
) a
where scene & 4 > 0 --过滤出只能给SRA用的部分
;
